use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary shell command and returns its output.
pub fn run_command(cmd: &str) -> Result<CommandResult, io::Error> {
    let output: Output = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()?;

    Ok(CommandResult {
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        exit_code: output.status.code().unwrap_or(-1),
    })
}

/// Executes a command with explicit arguments (avoids shell injection).
pub fn run_command_args(program: &str, args: &[&str]) -> Result<CommandResult, io::Error> {
    let output: Output = Command::new(program)
        .args(args)
        .output()?;

    Ok(CommandResult {
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        exit_code: output.status.code().unwrap_or(-1),
    })
}

/// Holds the result of an executed command.
#[derive(Debug)]
pub struct CommandResult {
    pub stdout:    String,
    pub stderr:    String,
    pub exit_code: i32,
}

impl CommandResult {
    /// Returns true if the command exited successfully.
    pub fn success(&self) -> bool {
        self.exit_code == 0
    }

    /// Formats the result as a single string suitable for sending back to the controller.
    pub fn to_response(&self) -> String {
        format!(
            "[exit:{}]\nSTDOUT:\n{}\nSTDERR:\n{}",
            self.exit_code, self.stdout, self.stderr
        )
    }
}
